local entries = ref.kinds["item"]["deDE"]
entries[86571] = { ["name"] = "Kangs Bindungsstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Erfüllt Euch mit Stein und gewährt eine Chance, nach dem Töten eines Gegners diesen in Stein zu hüllen. (Procchance: 33%, 1Min. Abklingzeit) (1 Stunde Abklingzeit)\n\"Die Steinbinder der Mogu nutzen diese runenverzierten Katalysatoren, um Fleisch in Stein zu verwandeln.\"" }
entries[86572] = { ["name"] = "Terrakottafragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nBenutzen: Beschwört einen Terrakottakrieger, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n\"Mit mächtiger Mogumagie erfüllt.\"\nVerkaufspreis:" }
entries[86573] = { ["name"] = "Fragment des Abschlusssteins", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Verwandelt in eine Mogustatue und kann 5 Min. lang nicht als Ziel erfasst werden. (30 Min Abklingzeit)\n\"Ein Fragment unbekannter Herkunft, das von uralter Magie erfüllt ist.\"" }
entries[86574] = { ["name"] = "Elixier des uralten Wissens", ["text"] = "Accountgebunden\nBenutzen: Erhöht die erhaltene Erfahrung 1 Stunde lang um 300%. Funktioniert nicht bei Spielercharakteren über Stufe 84.\n\"Ein leises Flüstern ist aus dem Fläschchen zu vernehmen.\"" }
entries[86575] = { ["name"] = "Kelch der Geheimnisse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Gebt Euch Eurem Zorn 10 Sek. lang hin. Während der Wirkungsdauer verwandelt Euch der nächste Todesstoß, den Ihr gegen einen Spielercharakter erzielt, 5.50 Sek. lang in einen Mogu. Als Mogu könnt Ihr keine anderen Aktionen ausführen, während Ihr den Gegner verhöhnt. (10 Min Abklingzeit)\n\"Rituale, um die Leichen gefallener Feinde zu entweihen, waren in der Mogukultur weit verbreitet.\"" }
entries[86576] = { ["name"] = "Dynastie des Stahls", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nBenutzen: Beschwört einen Klingentornado, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n\"Die Schwertkunst der Mantis ist ein sorgsam gehütetes Geheimnis.\"\nVerkaufspreis:" }
entries[86577] = { ["name"] = "Rute des Bernformens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Hüllt das Ziel in Bern und verhindert bis zu 1 Min. lang jegliche Handlung. Jeglicher Schaden zerbricht den Bern. Kann nicht gegen Spielercharaktere oder Ziele über Stufe 94 eingesetzt werden. (5 Min Abklingzeit)\n\"Wird von den Bernwebern der Mantis verwendet, um Konstruktionen oder gehärteten Bern herzustellen.\"" }
entries[86578] = { ["name"] = "Siegel des ewigen Kriegers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stellt 6 Sek. lang alle 1 Sek. 15% der Gesundheit und des Manas wieder her. Jeglicher erlittene Schaden entfernt die Raserei. Kann nur in Pandaria verwendet werden. Unwirksam bei Spielercharakteren über Stufe 94. (5 Min Abklingzeit)\n\"An Shek'zeers Elitewächter für treue Dienste verliehen.\"" }
entries[86579] = { ["name"] = "Abgefüllter Tornado", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Springt hoch in die Lüfte. Kann nur draußen verwendet werden. (2 Min Abklingzeit)\n\"Die Mantid haben vor langer Zeit gelernt, die Winde Pandarias ihrer Kaiserin gefügig zu machen.\"\nVerkaufspreis:" }
entries[86580] = { ["name"] = "Übergroßes Seerosenblatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Jäger , Schurke , Priester , Todesritter , Schamane , Magier , Hexenmeister , Mönch\nBenutzen: Gewährt eine Druidenfähigkeit abhängig von der Klasse und der Kampfrolle. Kann nur in Pandaria verwendet werden. (1 Stunde Abklingzeit)\n\"Ein ganzes Ökosystem liegt darin verborgen.\"" }
entries[86581] = { ["name"] = "Weitwassermuschelhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lässt Euch weit in die Ferne blicken und gewährt die Fähigkeit kleine Wassertropfen zu erzeugen. (10 Min Abklingzeit)\n\"Das Muschelhorn ist mit Jinyurunen beschrieben, die es dem Benutzer ermöglichen, die Sprache der Wellen zu verstehen.\"" }
entries[86582] = { ["name"] = "Wasserjuwel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 85\nBenutzen: Erhöht das Schwimmtempo um 50% und gestattet 10 Min. lang Unterwasseratmung. (1 Stunde Abklingzeit)\n\"Aus dem Schlund von Gokk'lok erbeutet.\"" }
entries[86583] = { ["name"] = "Schlachtbanner von Salyis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 85\nBenutzen: Versteckt sich 1 Sek. lang in den Schatten und beschwört einen Kriegsspäher von Salyis. Der Kriegsspäher zieht die Aufmerksamkeit von Monstern in der Nähe auf sich und rennt davon. (10 Min Abklingzeit)\n\"Mit dem Blut vieler glückloser Abenteurer getränkt.\"" }
entries[86584] = { ["name"] = "Gehärteter Panzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Wirft einen harten Panzer, der das Ziel aus dem Sattel stößt. Funktioniert nicht bei Zielen über Stufe 94. (15 Min Abklingzeit)\n\"Unfair!\"" }
entries[86585] = { ["name"] = "Goldenes Vlies", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nAnlegen: Getötete Gegner, die Erfahrung oder Ehre gewähren, können zusätzliche Goldbeute gewähren. (Procchance: 10%, 10Min. Abklingzeit)\n\"Wird unter den Saurok als Zeichen von Reichtum und Status betrachtet.\"\nVerkaufspreis:" }
entries[86586] = { ["name"] = "Pandarische Panflöte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Spielt auf der Panflöte, woraufhin Euch Kleintiere in der Nähe 15 Min. lang folgen. (1 Min Abklingzeit)" }
entries[86587] = { ["name"] = "Samen des ruhigen Wachstums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\nBenutzen: Beschwört einen ruhigen Sprössling, der Euch 10 Min. lang heilt. (1 Stunde Abklingzeit)\n\"Pulsierende Lebensenergie entspringt diesem Samen.\"\nVerkaufspreis:" }
entries[86588] = { ["name"] = "Pandarischer Raketenzünder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bereitet ein beeindruckendes Feuerwerk vor. (30 Min Abklingzeit)\n\"Hier geht's ab!\"" }
entries[86589] = { ["name"] = "Ai-Lis Himmelsspiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Nehmt das etwas verzerrte Aussehen des Ziel an. Hält 10 Min. lang an. (1 Stunde Abklingzeit)\n\"Von einem sich stetig bewegenden Wolkenring umgeben.\"" }
entries[86590] = { ["name"] = "Essenz der Brise", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Löst eine leichte Brise aus, die Eure Schritte leichter macht. Dieser Effekt zeigt nur in Pandaria Wirkung. (1 Stunde Abklingzeit)" }
entries[86591] = { ["name"] = "Magische Banane", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wirft eine magische Banane auf den Boden, die die nächste Person zu Fall bringen wird, die über sie läuft. (2 Std. Abklingzeit)" }
entries[86592] = { ["name"] = "Ho-zen-Friedenspfeife", ["text"] = "Benötigt Stufe 90\nBenutzen: Erhöht den Ruf bei den Einwohnern Pandarias um 1000. (7 Tagen Abklingzeit)" }
entries[86593] = { ["name"] = "Ho-zen-Strandball", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Macht Euch auf Sommerspaß gefasst! (1 Stunde Abklingzeit)" }
entries[86594] = { ["name"] = "Pfeife des hilfreichen Nupsi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ruft das hilfreiche Nuspi, das für Euch nach Futter suchen und Geschenke zurückbringen wird. (2 Std. Abklingzeit)\n\"Darauf wurde wohl heftig herumgekaut.\"" }
entries[86595] = { ["name"] = "Beutel mit hilfreichen Sachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[86596] = { ["name"] = "Nats Angelstuhl", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Rechtsklicken, um einen bequemen Angelstuhl aufzustellen. (5 Min Abklingzeit)\n\"Hat sogar einen Getränkehalter!\"" }
entries[86597] = { ["name"] = "Waffenkette aus lebendigem Stahl", ["text"] = "Wird beim Anlegen gebunden\nBenötigt Stufe 85\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Eure Waffenkunde um 200 erhöht. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen der Waffenkette wird der Gegenstand seelengebunden." }
entries[86598] = { ["name"] = "Vor'thik-Eier", ["text"] = "Questgegenstand" }
entries[86599] = { ["name"] = "Geistereisenschildstachel", ["text"] = "Wird beim Anlegen gebunden\nBenötigt Stufe 85\nBenutzen: Bringt einen Geistereisenstachel an Eurem Schild an, der beim Blocken manchmal 280 Schaden verursacht.\n\nDurch das Anbringen des Geistereisenstachel wird der Gegenstand seelengebunden.\nVerkaufspreis:" }
entries[86607] = { ["name"] = "Goblindrachengewehr - Nr. II", ["text"] = "Benötigt Stufe 85\nBenutzen: Entfesselt eine Blitzentladung, die Zielen in einem 10 Meter großen kegelförmigen Bereich vor dem Wirkenden 4 Sek. lang alle 0.5 Sek. 4500 Naturschaden zufügt.\n\nKann während der Bewegung gewirkt werden. (30 Sek. Abklingzeit)\n50 Aufladungen\nVerkaufspreis:" }
entries[86616] = { ["name"] = "Schreckensbernfokus", ["text"] = "Questgegenstand\n\"Konzentrierte Angst, die in kristallisiertem Kyparitharz gebunden wurde.\"" }
entries[86623] = { ["name"] = "Blingtron-4000-Geschenkpaket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Worauf wartet Ihr? MACHT ES AUF!\"\n<Zum Öffnen rechtsklicken>" }
