entries[87250] = { ["name"] = "Rakete mit abgereichertem Kyparium", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Höhepunkt goblinischer Ingenieurskunst! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
entries[87251] = { ["name"] = "Geosynchroner Weltendreher", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Apparatur, die die Welt selbst unter Euch rotieren lässt! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
entries[87252] = { ["name"] = "Dampfgefüllter Ballon", ["text"] = "\"Viel Glück!\"\nVerkaufspreis:" }
entries[87253] = { ["name"] = "Unerschöpfliches Resteessen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen: Richtet ein Resteessen für Eure gesamte Gruppe oder Euren gesamten Schlachtzug her.\n\nStellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. (30 Min Abklingzeit)\nVerkaufspreis:" }
entries[87257] = { ["name"] = "Arkaner Familiarstein", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: [Familiar Stone] (1)\nBenutzen: Beschwört einen arkanen Familiar, der Euch folgt, und gibt ihn wieder frei. Der Familiar wird verschwinden, wenn Ihr Euch ausloggt." }
