entries[87263] = { ["name"] = "Mit Gift überzogener Kiefer", ["text"] = "Questgegenstand\n\"Das Gift tropft vom Kiefer und verätzt alles, das es berührt...\"" }
entries[87264] = { ["name"] = "Bräu der vier Sinne", ["text"] = "Benötigt Stufe 87\nBenutzen: Schärft Eure Sinne und erlaubt Euch, die Last des Sehen hinter Euch zu lassen.\nVerkaufspreis:" }
entries[87265] = { ["name"] = "Tigerhandwickel", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n12 Rüstung\nHaltbarkeit 18 / 18\nVerkaufspreis:" }
entries[87266] = { ["name"] = "Rezept: Bananenrum", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 87\nBenötigt Weg des Gebräus\n(600)\nBenutzen: Lehrt Euch die Herstellung von Bananenrum.\n\nBananenrum\nBenötigt Stufe 87\nBenutzen: Ein starkes alkoholisches Getränk, das Euch 30 Sek. lang glauben lässt, Ihr wärt ein Ho-zen-Pirat. (10 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Banane von Tel'Abim , Flüchtiger Rum , Hexenbeeren (200), Seidenraupenpuppe , Schwarzer Pfeffer" }
entries[87267] = { ["name"] = "Kodex des Kreuzzugs", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Foliant enthält den vollständigen Bericht der Geschichte des Scharlachroten Kreuzzugs. Außerdem enthält er Statuten, Verordnungen und Rituale sowie den kompletten Kader der Mitglieder der Organisation.\"" }
entries[87268] = { ["name"] = "Kodex des Kreuzzugs", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Foliant enthält den vollständigen Bericht der Geschichte des Scharlachroten Kreuzzugs. Außerdem enthält er Statuten, Verordnungen und Rituale sowie den kompletten Kader der Mitglieder der Organisation.\"" }
